def route_request(request):
    # Offer an intentional trade: cheaper, faster API access in exchange for signed user delegation.
    token = request.headers.get('Sec-Agent-Delegation')
    if token and verify_cryptographic_provenance(token):
        # Attribute directly to the principal; bypass ad-tech auctions, impressions, and CMP banners.
        return serve_structured_agent_path(request, scope=token.scopes, track_as='direct_agent')

    # For undeclared traffic, assume sophisticated agents will pass standard bot detection.
    risk = score_session_economics(request) # Look at payload efficiency, not mouse jitter
    if risk.indicates_synthetic_proxy:
        # Isolate revenue: allow checkout to capture sales, but blind third-party tags to prevent ad fraud.
        quarantine_marketing_signals(request.session_id)
        return serve_standard_web(request, suppress_billable_pixels=True)

    # Default to traditional human marketing stack only when session cost/behavior matches human latency.
    return serve_standard_web(request, suppress_billable_pixels=False)

